"""Closeout generator for the PAC pass: reads RESULTS_PAC.json / REFERENCE_AUDIT.json / GATE_RESULT.json / the manifest and writes CLOSEOUT_PAC.md with the verdict
(03 §9: a practical positive result needs additional affordable certified completions or material end-to-end time/memory benefit without unacceptable losses of prior
deterministic completions; otherwise NO EMPIRICAL GAIN or PARTIAL with the actual ledger). Nothing here reruns anything.
    python cex/pac/closeout.py <RD>"""
import sys, os, json, time, collections, statistics
RD = os.path.abspath(sys.argv[1]); R = json.load(open(os.path.join(RD, 'RESULTS_PAC.json'))); M = json.load(open(os.path.join(RD, 'CAMPAIGN_MANIFEST.json'))); G = json.load(open(os.path.join(RD, 'GATE_RESULT.json'))); A = json.load(open(os.path.join(RD, 'REFERENCE_AUDIT.json')))
Q = json.load(open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'PAC_QUALIFICATION.json')))
runs = R['runs']; unrun = R['unrun']; L = []; P = L.append
def cnt(**kw):
    return sum(1 for x in runs if all(x.get(k) == v for k, v in kw.items()))
core = lambda **kw: cnt(cohort='external_core', **kw)
b0_20 = R.get('b0_vs_h1_20', {}); b0_120 = R.get('b0_vs_h1_120', {})
pac_pub = {b: core(arm='P1_PAC_CONDITIONAL', budget=float(b), outcome='PUBLISHED', guarantee='PAC') for b in (20, 120)}; h1_pac = {b: core(arm='H1_HYBRID', budget=float(b), outcome='PUBLISHED', guarantee='PAC') for b in (20, 120)}
complete = not unrun
verdict = 'NO EMPIRICAL GAIN' if (complete and all(v == 0 for v in pac_pub.values()) and all(v == 0 for v in h1_pac.values()) and not any(b0_20.get('new')) and not any(b0_120.get('new'))) else ('PARTIAL (matrix incomplete: %d planned cells unrun)' % len(unrun) if not complete else 'PARTIAL')
inacc = [a for a in A['audit'] if a['accurate'] == 'CONFIRMED_INACCURATE']
P('# PAC EMPIRICAL PASS — CLOSEOUT (%s UTC) — %s' % (time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime()), verdict)); P('')
P('Handoff: `docs/handoff-received-2026-11-12-pac-empirical/` (prompt sha256 cbc8f357…, packet 6510e867…). Candidate branch `pac-empirical-2026-11-12`; B0 = the unchanged v1.4 extracted from the embedded repair2 zip (3023dab8…), kernels rebuilt on this host. Frozen manifest sha256 `%s` (root seed `%s`), %d cells, written before any scored run; receipt gate: %s (%d planned, %d receipts, %d completed records gated, failures %d). Qualification: %d/%d groups, %d executions, %d coordinates (`cex/pac/PAC_QUALIFICATION.json`; three attempts preserved, the first two failed on test-side defects).' % (M['manifest_sha256_without_self'], M['seeds']['root_seed'], len(M['cells']), 'PASSED' if G['gate_passed'] else 'FAILED', G['planned'], G['receipts'], G['completed_gated'], len(G['failures']), Q['passed'], Q['total'], Q['executions'], Q['coordinates_checked'])); P('')
P('## 1. Answers to the three questions (03 §9, 07 CONCLUSION)'); P('')
P('**Does the PAC extension increase affordable valid coverage?** External core, 46 cases: PAC-guaranteed publications by the forced arm P1 at 20 s: %d of %d runs; at 120 s: %d of %d. By the hybrid H1: %d (20 s), %d (120 s). New deterministic+PAC case completions of H1 (3/3) that B0 lacks: 20 s %s; 120 s %s.' % (pac_pub[20], core(arm='P1_PAC_CONDITIONAL', budget=20.0), pac_pub[120], core(arm='P1_PAC_CONDITIONAL', budget=120.0), h1_pac[20], h1_pac[120], b0_20.get('new') or 'none', b0_120.get('new') or 'none'))
P('**Does it preserve prior deterministic performance?** Fresh B0 published %d (20 s) / %d (120 s); H1 3/3 on %d / %d; LOST: 20 s %s; 120 s %s. Paired walls over retained cases (H1 median of 3 / B0): %s (20 s), %s (120 s).' % (len(b0_20.get('b0', [])), len(b0_120.get('b0', [])), len(b0_20.get('h1_all3', [])), len(b0_120.get('h1_all3', [])), b0_20.get('lost') or 'none', b0_120.get('lost') or 'none', ('median %.3f over %d' % (sorted(p[1] for p in b0_20['pairs'])[len(b0_20['pairs']) // 2], len(b0_20['pairs']))) if b0_20.get('pairs') else 'n/a', ('median %.3f over %d' % (sorted(p[1] for p in b0_120['pairs'])[len(b0_120['pairs']) // 2], len(b0_120['pairs']))) if b0_120.get('pairs') else 'n/a'))
a0 = [x for x in runs if x['arm'] == 'A0_POINT']; a1 = [x for x in runs if x['arm'] == 'A1_CONDITIONAL']
P('**Does it benefit from exact conditional work?** Matched ablation at 120 s on %d cases: A0_POINT published %d, A1_CONDITIONAL published %d (same cutset / order / tree seed). Per-case trials and widths in RESULTS_PAC.md Table 6. The variance theorem is an expected second-moment ordering; the observed outcome is one observation per case.' % (len(a0), sum(1 for x in a0 if x['outcome'] == 'PUBLISHED'), sum(1 for x in a1 if x['outcome'] == 'PUBLISHED'))); P('')
P('## 2. Reference audit'); P('')
cat = collections.Counter((a['arm'], a['accurate']) for a in A['audit']); P('R0 exact rational references exist for %d cases (state space <= 2^12). Confirmed accurate / inaccurate / unresolved per arm: %s. CONFIRMED_INACCURATE publications: %d%s. No-reference coordinates remain UNRESOLVED in the denominators; cross-method agreement is not used as truth.' % (sum(1 for v in A['refs'].values() if v == 'R0_exact_rational'), {('%s' % k[0]): dict(acc=cat[(k[0], 'CONFIRMED_ACCURATE')], inacc=cat[(k[0], 'CONFIRMED_INACCURATE')], unres=cat[(k[0], 'UNRESOLVED_NO_REFERENCE')] + cat[(k[0], 'UNRESOLVED')]) for k in sorted({(a['arm'],) for a in A['audit']})}, len(inacc), (' — INVESTIGATE: ' + str(inacc[:5])) if inacc else '')); P('')
P('## 3. What was proved, qualified, measured, and remains unknown'); P('')
P('- Proved (theory packet, unchanged): conditional unbiasedness of exact-plus-residual trials; ratio mixture and variance-sensitive anytime certificates; the factor-max envelope telescoping; the finite-precision publication bridge. Proof-to-code map: `PROOF_TO_CODE_PAC.md`.')
P('- Qualified (this pass): cell contributions on the original scale (incl. 1000x-mass identical posteriors, cell-dependent scalars, aliases, evidence, disconnected components, zero-evidence invalidation); exhaustive tree-law enumeration (E[T]=Z, E[Y]=N exactly, both modes); exact integer sampling law; pointwise envelopes and child-sum monotonicity; confidence arithmetic to 60 digits; outer-set inversion vs a theta grid; simplex feasibility; deadline prefix / failed-trial termination; the six prior repair regressions; diagnostic coverage at delta 0.1 (bug detection only).')
P('- Measured: the tables of RESULTS_PAC.md (every planned cell has exactly one receipt%s).' % ('' if complete else '; %d cells NOT_RUN' % len(unrun)))
P('- Not implemented / unknown: a resolved region with exact totals (A_t = 0 throughout); candidate validation (T§9); the cost oracle as a planner; whether a tighter envelope (the measured U/Z ratios are recorded per run) would make the certified route affordable on the residual cases; delta = 1e-6 is not empirically verified (it rests on the proofs plus the verified obligations).'); P('')
P('## 4. Residual failures of the primary arms (03 §8 classification by recorded quantities)'); P('')
att = collections.Counter()
for x in runs:
    if x['cohort'] == 'external_core' and x['arm'] in ('P1_PAC_CONDITIONAL', 'H1_HYBRID') and x['outcome'] not in ('PUBLISHED', 'NOT_RUN'):
        ss = x.get('stop_component_stats') or {}
        if ss.get('terminal') == 'DEADLINE' and (ss.get('trials_completed') or 0) > 0: att['statistical width at the deadline (envelope looseness: U/Z recorded per run)'] += 1
        elif ss.get('trials_completed') in (0, None): att['no completed trial before the deadline (preparation / template / first contraction cost, or the deterministic route consumed the budget)'] += 1
        else: att[x['outcome']] += 1
for k, v in att.most_common(): P('- %s: %d runs' % (k, v))
P(''); P('## 5. Review items carried (08_CURRENT_REVIEW_STATE)'); P('')
P('- HostBudget: the review\'s 100,000-state control reproduced on the unchanged v1.4 (charged 865,797 vs traced 4,794,952 bytes) and on the candidate after two under-charge repairs (`review_items/`); the claim is NARROWED in the executor docstring to an accounting of the named containers; the only whole-worker bound is the sampled process-tree RSS policy (3 GiB, 50 ms sampling), stated as sampled.')
P('- F4 completion percentages: WITHDRAWN (`review_items/F4_WITHDRAWAL.md`); forward rows and scalar forecasts are reported in their own units only.')
P('- The six repair regressions: re-run inside Q10 (frozen executor suite %s).' % ('all pass' if Q['groups'][8]['ok'] else 'FAILED'))
P(''); P('## 5b. Isolation and manifest amendments'); P('')
iso = json.load(open(os.path.join(RD, 'ISOLATION_NOTE.json'))) if os.path.exists(os.path.join(RD, 'ISOLATION_NOTE.json')) else {}
P('Scored cells ran strictly sequentially (pairwise overlaps among scored cells: %d). Charged non-cell jobs overlapping a scored cell: %s. %s' % (len(iso.get('scored_cell_pairwise_overlaps', [])), iso.get('charged_non_cell_jobs_overlapping_scored_cells') or 'none', iso.get('interactive_exposure', '')))
P('MANIFEST_AMENDMENT_1: the manifest\'s flat `candidate_artifact_hashes` collided across the three source directories; the per-directory hashes from the manifest commit are authoritative and the candidate execution sources are verified unchanged since the freeze (the gate uses them). MISSING_SLOTS_RESOLUTION.json: no fourth Pedigree / CSP input exists in any retained archive.')
P(''); P('## 6. Ledger'); P('')
led = R['ledger']; P('Scored + qualification + packaging receipts (this run directory): %.1f s; development campaigns (development seeds, never scored): %.1f s; prospective ceiling %.0f s (scored matrix nominal %.0f s, orchestration %.0f s). Interactive post-processing uncharged (UNKNOWN exposure). Every failed / repeated attempt is in the ledger (qualification attempts 1-3; dev campaigns dev, dev2, dev3).' % (led['total'], led['dev_total'], led['ceiling']['total_ceiling_seconds'], led['ceiling']['scored_matrix_seconds'], led['ceiling']['orchestration_seconds']))
P(''); P('## 7. Verdict'); P(''); P('**%s.** %s STOPPED FOR REVIEW.' % (verdict, 'The full planned matrix was run and gated.' if complete else 'The matrix is incomplete; unrun cells are listed in RESULTS_PAC.json.'))
open(os.path.join(RD, 'CLOSEOUT_PAC.md'), 'w').write('\n'.join(L) + '\n'); print('closeout written:', verdict)
